Set Default Goal Selector "!".
Local Open Scope nat_scope.
Local Notation "a && b" := (andb a b).

Definition tm : TM := fun '(q, s) =>
  match q, s with
  | A, S0 => Some (S1, R, B)  | A, S1 => Some (S0, L, F)
  | B, S0 => Some (S1, L, C)  | B, S1 => Some (S0, L, A)
  | C, S0 => Some (S1, R, A)  | C, S1 => Some (S0, R, D)
  | D, S0 => None             | D, S1 => Some (S1, R, E)
  | E, S0 => Some (S1, L, A)  | E, S1 => Some (S1, R, C)
  | F, S0 => Some (S0, L, B)  | F, S1 => Some (S0, R, C)
  end.

Notation "c -->* c'" := (c -[ tm ]->* c') (at level 40).
Notation "c -->+ c'" := (c -[ tm ]->+ c') (at level 40).

