Lemma trp : forall P Q P' Q', P -->+ Q -> P = P' -> Q = Q' -> P' -->+ Q'.
Proof. intros. subst. assumption. Qed.
Lemma off_200 : forall j, 200 <= j -> exists j', j = j' + 200.
Proof. intros j H. exists (j - 200). lia. Qed.

