Definition endC1L : list nat := [186; 183; 171; 186; 180; 141; 183; 210; 207; 170; 81; 182; 196; 125; 174; 176; 135; 132; 90; 204; 128; 127; 190; 147; 133; 81; 133; 148; 208; 197; 135; 173; 186; 139; 136; 148; 65; 162; 99; 199; 179; 196; 179; 178; 190; 120; 179; 169; 141; 189; 161; 68; 139; 184; 59; 203; 132; 181; 186; 183; 80; 189].
Definition endC2L : list nat := [31; 39; 83; 49; 59; 124; 46; 4; 7; 81; 247; 45; 20; 163; 63; 62; 151; 170; 254; 13; 160; 171; 45; 134; 161; 259; 161; 120; 17; 36; 162; 67; 35; 138; 140; 117; 293; 103; 231; 47; 88; 49; 52; 56; 29; 174; 57; 80; 132; 34; 96; 291; 143; 44; 311; 24; 167; 67; 35; 43; 259; 35].

Definition tpl (t : nat) : MC := nth t tplL (mkMC [] [] B).
Definition nxt t := nth t nxtL 0.
Definition dj t := nth t djL 0.
Definition pot t := nth t potL 0.
Definition endT t := nth t endTL 0.
Definition endC1 t := nth t endC1L 0.
Definition endC2 t := nth t endC2L 0.

Definition cfg (t k j : nat) : Q * tape := cden [k; j] (tpl t).

(** ** The checks *)

Definition sR : list Lin := [mkLin 1 [1]; mkLin 0 [0; 1]].
Definition sE : list Lin := [mkLin 0 []; mkLin 200 [0; 1]].

Definition roundOK (t : nat) : bool :=
  rule tm KK norm01 (Nat.pow 2 12) (tpl t) sR (tpl (nxt t)) [mkLin 0 [1]; mkLin (dj t) [0; 1]].
Definition endOK (t : nat) : bool :=
  rule tm KK norm01 (Nat.pow 2 18) (tpl t) sE (tpl (endT t)) [mkLin (endC1 t) [0; 1]; mkLin (endC2 t) []].
Definition tablesOK (t : nat) : bool :=
  (nxt t <? nT) && (endT t <? nT) && (pot t + 2 <=? pot (nxt t) + dj t) && (pot t <=? 15) &&
  (215 <=? endC2 t + 2 * endC1 t + pot (endT t)).

Lemma forall_lt : forall (p : nat -> bool), forallb p (seq 0 nT) = true -> forall t, t < nT -> p t = true.
Proof.
  intros p H t Ht. rewrite forallb_forall in H. apply H. apply in_seq. lia.
Qed.

Lemma tables_ok : forallb tablesOK (seq 0 nT) = true.
Proof. vm_compute. reflexivity. Qed.
Lemma rounds_ok : forallb roundOK (seq 0 nT) = true.
Proof. vm_compute. reflexivity. Qed.
Lemma ends_ok : forallb endOK (seq 0 nT) = true.
Proof. vm_compute. reflexivity. Qed.

Lemma start_ok : rule tm KK norm01 (Nat.pow 2 21) (mkMC [] [] A) [] (tpl 31) [mkLin 38 []; mkLin 163 []] = true.
Proof. vm_compute. reflexivity. Qed.

(** ** The invariant *)

Definition Good (c : Q * tape) : Prop := exists t k j, t < nT /\ c = cfg t k j /\ 215 <= j + 2 * k + pot t.

Lemma table_facts : forall t, t < nT -> nxt t < nT /\ endT t < nT /\ pot t + 2 <= pot (nxt t) + dj t /\
  pot t <= 15 /\ 215 <= endC2 t + 2 * endC1 t + pot (endT t).
Proof.
  intros t Ht. pose proof (forall_lt _ tables_ok t Ht) as H. unfold tablesOK in H.
  apply andb_prop in H as [H H5]. apply andb_prop in H as [H H4]. apply andb_prop in H as [H H3].
  apply andb_prop in H as [H1 H2].
  apply Nat.ltb_lt in H1, H2. apply Nat.leb_le in H3, H4, H5. auto.
Qed.

Lemma good_step : forall c, Good c -> exists c', Good c' /\ c -->+ c'.
Proof.
  intros c [t [k [j [Ht [-> Hp]]]]].
  destruct (table_facts t Ht) as [Hn [He [Hpot [H15 Hend]]]].
  destruct k as [| k].
  - destruct (off_200 j ltac:(lia)) as [j' ->].
    pose proof (rule_sound tm KK norm01 norm01_den _ _ _ _ _ (forall_lt _ ends_ok t Ht) [0; j']) as H.
    exists (cfg (endT t) (j' + endC1 t) (endC2 t)). split.
    + exists (endT t), (j' + endC1 t), (endC2 t). repeat split; [assumption | lia].
    + unfold cfg. eapply trp; [exact H | f_equal; unfold sE; evs_eq | f_equal; evs_eq].
  - pose proof (rule_sound tm KK norm01 norm01_den _ _ _ _ _ (forall_lt _ rounds_ok t Ht) [k; j]) as H.
    exists (cfg (nxt t) k (j + dj t)). split.
    + exists (nxt t), k, (j + dj t). repeat split; [assumption | lia].
    + unfold cfg. eapply trp; [exact H | f_equal; unfold sR; evs_eq | f_equal; evs_eq].
Qed.

Lemma start_good : c0 -->+ cfg 31 38 163.
Proof. exact (rule_sound tm KK norm01 norm01_den _ _ _ _ _ start_ok []). Qed.

Theorem nonhalt : ~ halts tm c0.
Proof.
  apply multistep_nonhalt with (c' := cfg 31 38 163); [apply progress_evstep; exact start_good |].
  apply progress_nonhalt with (P := Good).
  - intros c Hc. destruct (good_step c Hc) as [c' [H1 H2]]. eauto.
  - exists 31, 38, 163. split; [unfold nT; lia |]. split; [reflexivity |]. vm_compute. lia.
Qed.

Print Assumptions nonhalt.